package com.andye.warmod.item;
import com.andye.warmod.item.component.ModDataComponents;import com.andye.warmod.item.component.RocketLauncherMode;import com.andye.warmod.rocket.RocketLaunchService;import java.util.function.Consumer;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import net.minecraft.sounds.SoundEvents;import net.minecraft.sounds.SoundSource;import net.minecraft.world.InteractionHand;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.component.TooltipDisplay;import net.minecraft.world.level.Level;
public final class RocketLauncherItem extends Item {public RocketLauncherItem(Properties p){super(p);}@Override public InteractionResult use(Level level,Player player,InteractionHand hand){ItemStack launcher=player.getItemInHand(hand);RocketLauncherMode mode=launcher.getOrDefault(ModDataComponents.ROCKET_LAUNCHER_MODE,RocketLauncherMode.HE);if(player.isShiftKeyDown()){if(!level.isClientSide()){mode=mode.next();launcher.set(ModDataComponents.ROCKET_LAUNCHER_MODE,mode);player.sendSystemMessage(Component.literal("Rocket Launcher mode: "+mode));}return level.isClientSide()?InteractionResult.SUCCESS:InteractionResult.SUCCESS_SERVER;}if(level.isClientSide()||!(level instanceof ServerLevel server)||!(player instanceof ServerPlayer shooter))return InteractionResult.SUCCESS;if(shooter.getCooldowns().isOnCooldown(launcher))return InteractionResult.PASS;ItemStack ammunition=findAmmunition(shooter,mode);if(ammunition.isEmpty()&&!shooter.hasInfiniteMaterials()){shooter.sendSystemMessage(Component.literal("Rocket Launcher requires "+mode.ammunition().getName(new ItemStack(mode.ammunition())).getString()));return InteractionResult.SUCCESS_SERVER;}if(!RocketLaunchService.launch(server,shooter,mode.payload())){shooter.sendSystemMessage(Component.literal("Rocket launch failed"));return InteractionResult.SUCCESS_SERVER;}if(!shooter.hasInfiniteMaterials())ammunition.shrink(1);shooter.getCooldowns().addCooldown(launcher,mode.payload().cooldown());server.playSound(null,shooter.blockPosition(),SoundEvents.FIREWORK_ROCKET_LAUNCH,SoundSource.PLAYERS,1F,.78F);shooter.setDeltaMovement(shooter.getDeltaMovement().add(shooter.getLookAngle().scale(-.12)));shooter.swing(hand);return InteractionResult.SUCCESS_SERVER;}
 private static ItemStack findAmmunition(ServerPlayer player,RocketLauncherMode mode){for(ItemStack stack:player.getInventory().getNonEquipmentItems())if(stack.is(mode.ammunition()))return stack;ItemStack off=player.getOffhandItem();return off.is(mode.ammunition())?off:ItemStack.EMPTY;}
 @Override public void appendHoverText(ItemStack stack,TooltipContext context,TooltipDisplay display,Consumer<Component> builder,TooltipFlag flag){builder.accept(Component.literal("Mode: "+stack.getOrDefault(ModDataComponents.ROCKET_LAUNCHER_MODE,RocketLauncherMode.HE)));builder.accept(Component.literal("Crouch-use to cycle"));}}